import numpy as np
lines=open('opt1.xyz').read().split('\n')
n=int(lines[0]); ats=[]
for l in lines[2:2+n]:
    p=l.split(); ats.append((p[0], np.array(list(map(float,p[1:4])))))
P=[a[1] for a in ats]
def d(i,j): return np.linalg.norm(P[i]-P[j])
pairs=[(0,1,'V-O1'),(0,12,'V-O2'),(0,5,'V-N1'),(0,8,'V-N2'),(0,17,'V-Cipso'),
(1,2),(2,3),(3,4),(4,5),(2,6),(4,7),(8,9),(9,10),(10,11),(11,12),(9,13),(11,14),
(5,15),(15,16),(16,8),(17,18),(18,19),(19,20),(20,21),(21,22),(22,17)]
for p in pairs:
    if len(p)==2: i,j=p; print(i,j,round(d(i,j),3))
    else: i,j,nm=p; print(nm, round(d(i,j),3))
EOF
